-- Airlinerra airport registry design.
-- Commit to staging only. NOT applied to any database by this GitHub commit.
-- Approved rows are not generated by this migration.

create table if not exists public.airports (
  id bigint generated always as identity primary key,
  iso_country text not null check (iso_country ~ '^[A-Z]{2}$'),
  name text not null,
  icao_code text unique,
  iata_code text,
  ourairports_id bigint unique,
  latitude_deg double precision check (latitude_deg between -90 and 90),
  longitude_deg double precision check (longitude_deg between -180 and 180),
  airport_category text check (
    airport_category in ('Local','Regional','Medium','Large','Major Hub','Mega Hub')
  ),
  approval_status text not null default 'REVIEW'
    check (approval_status in ('REVIEW','APPROVED','EXCLUDED')),
  civilian_access text not null default 'UNVERIFIED'
    check (civilian_access in ('UNVERIFIED','YES','NO','CONDITIONAL')),
  operational_limits text,
  source_url text,
  verified_at timestamptz,
  is_active boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint airport_approved_is_verified check (
    approval_status <> 'APPROVED'
    or (airport_category is not null
      and civilian_access in ('YES','CONDITIONAL')
      and verified_at is not null
      and source_url is not null)
  ),
  constraint airport_active_requires_approval check (
    not is_active or approval_status = 'APPROVED'
  )
);

create index if not exists airports_country_category_idx
  on public.airports (iso_country, airport_category);
create index if not exists airports_playable_idx
  on public.airports (approval_status, is_active);

create table if not exists public.airport_runways (
  id bigint generated always as identity primary key,
  airport_id bigint not null references public.airports(id) on delete cascade,
  source_runway_id bigint unique,
  runway_ident text,
  length_m numeric(8,1) not null check (length_m > 0),
  surface text not null,
  surface_verified boolean not null default false,
  runway_operational boolean not null default true,
  last_verified_at timestamptz,
  constraint airport_runway_unique_ident unique (airport_id, runway_ident)
);

create index if not exists airport_runways_airport_idx
  on public.airport_runways (airport_id);

create table if not exists public.airport_restrictions (
  id bigint generated always as identity primary key,
  airport_id bigint not null references public.airports(id) on delete cascade,
  restriction_type text not null,
  description text not null,
  max_takeoff_mass_kg numeric(12,1),
  effective_from timestamptz,
  effective_until timestamptz,
  source_url text,
  recorded_at timestamptz not null default now(),
  check (effective_until is null or effective_from is null
    or effective_until >= effective_from)
);

create index if not exists airport_restrictions_airport_idx
  on public.airport_restrictions (airport_id);

-- Row-level access prevents anonymous writes. Production access is for approved
-- active airports only. Service-role imports require separately approved tooling.
alter table public.airports enable row level security;
alter table public.airport_runways enable row level security;
alter table public.airport_restrictions enable row level security;

create policy airports_public_read_approved on public.airports
  for select to anon, authenticated using (approval_status = 'APPROVED' and is_active);

create policy runway_public_read_approved on public.airport_runways
  for select to anon, authenticated using (
    exists (
      select 1 from public.airports a
      where a.id = airport_runways.airport_id
        and a.approval_status = 'APPROVED'
        and a.is_active
    )
  );

create policy restrictions_public_read_approved on public.airport_restrictions
  for select to anon, authenticated using (
    exists (
      select 1 from public.airports a
      where a.id = airport_restrictions.airport_id
        and a.approval_status = 'APPROVED'
        and a.is_active
    )
  );

-- Future import jobs must require a verified qualifying runway >=1200 m
-- with confirmed asphalt/concrete and civilian permission before activating
-- an airport. Do not apply this migration before the Airlinerra-only Supabase
-- project is created and its target schema reviewed.
